div.script:
document.querySelectorAll('.mo_site .faq-q').forEach(function(btn){
  btn.addEventListener('click', function(){
    var item = btn.closest('.faq-item');
    var wasOpen = item.classList.contains('open');
    document.querySelectorAll('.mo_site .faq-item.open').forEach(function(i){ i.classList.remove('open'); });
    if(!wasOpen){ item.classList.add('open'); }
  });
});
